package au.com.endurancecoach.core;
import org.json.*;
import org.junit.Test;
import java.time.LocalDate;
import static org.junit.Assert.*;
public class NutritionTargetsTest {
 private JSONObject row(String scope,String date,int revision,double kcal,String status){return new JSONObject().put("target_id",(scope.equals("daily")?"nutrition-":"baseline-")+date).put("revision",revision).put("scope",scope).put("date",date).put("calories_kcal",kcal).put("protein_g",JSONObject.NULL).put("carbohydrate_g",JSONObject.NULL).put("fat_g",JSONObject.NULL).put("weight_goal_kg",JSONObject.NULL).put("weight_goal_date","").put("weight_change_kg_per_week",JSONObject.NULL).put("training_type","").put("exercise_included",true).put("source","Synthetic Coach").put("created_at","2026-11-08T01:00:00.000Z").put("reason","Synthetic approved target").put("status",status);}
 private NutritionTargets.Target target(JSONArray rows,String date){return NutritionTargets.forDay(rows,LocalDate.parse(date),new JSONArray());}
 @Test public void exactDayWinsAndWorkoutEnergyIsNeverAdded(){JSONArray rows=new JSONArray().put(row("baseline","2026-11-08",1,2400,"approved")).put(row("daily","2026-11-09",1,3100,"approved"));JSONArray plan=new JSONArray().put(new JSONObject().put("workout_id","w").put("revision",1).put("date","2026-11-09").put("type","run").put("status","scheduled").put("calories_burned",900));assertEquals(3100,NutritionTargets.forDay(rows,LocalDate.parse("2026-11-09"),plan).calories,0);assertEquals(2400,target(rows,"2026-11-10").calories,0);}
 @Test public void futureBaselineDoesNotRewritePastDays(){JSONArray rows=new JSONArray().put(row("baseline","2026-11-08",1,2400,"approved")).put(row("baseline","2026-11-15",1,2500,"approved"));assertEquals(2400,target(rows,"2026-11-14").calories,0);assertEquals(2500,target(rows,"2026-11-15").calories,0);assertNull(target(rows,"2026-11-07"));}
 @Test public void draftDoesNotReplaceApprovedAndCancelFallsBack(){JSONArray rows=new JSONArray().put(row("baseline","2026-11-08",1,2400,"approved")).put(row("daily","2026-11-09",1,3100,"approved")).put(row("daily","2026-11-09",2,3300,"draft"));assertEquals(3100,target(rows,"2026-11-09").calories,0);rows.put(row("daily","2026-11-09",3,3100,"cancelled"));assertEquals(2400,target(rows,"2026-11-09").calories,0);}
 @Test public void revisionsDoNotDependOnArrivalOrder(){JSONArray rows=new JSONArray().put(row("daily","2026-11-09",2,3200,"approved")).put(row("daily","2026-11-09",1,3100,"approved"));assertEquals(3200,target(rows,"2026-11-09").calories,0);}
 @Test public void duplicateSameRevisionConflictsAreRejected(){JSONObject a=row("daily","2026-11-09",1,3100,"approved");assertEquals(1,NutritionTargets.validate(new JSONArray().put(a).put(new JSONObject(a.toString()))).length());assertThrows(IllegalArgumentException.class,()->NutritionTargets.validate(new JSONArray().put(a).put(row("daily","2026-11-09",1,3200,"approved"))));}
 @Test public void optionalMacrosStayUnknownAndWeightSettingsCanUseBaseline(){JSONObject baseline=row("baseline","2026-11-08",1,2400,"approved").put("protein_g",160).put("weight_goal_kg",90).put("weight_goal_date","2027-03-01");JSONObject daily=row("daily","2026-11-09",1,3100,"approved");NutritionTargets.Target t=target(new JSONArray().put(baseline).put(daily),"2026-11-09");assertNull(t.protein);assertNull(t.carbohydrate);assertEquals(90,t.weightGoalKg,0);assertEquals("2027-03-01",t.weightGoalDate);}
 @Test public void planChangeFlagsReviewWithoutRecalculating(){JSONObject daily=row("daily","2026-11-09",1,3100,"approved");JSONArray plan=new JSONArray().put(new JSONObject().put("workout_id","w").put("revision",2).put("date","2026-11-09").put("type","run").put("status","scheduled").put("created_at","2026-11-08T02:00:00.000Z"));NutritionTargets.Target t=NutritionTargets.forDay(new JSONArray().put(daily),LocalDate.parse("2026-11-09"),plan);assertTrue(t.trainingChanged);assertEquals(3100,t.calories,0);assertEquals("Run",t.trainingType);}
 @Test public void invalidTargetsDoNotBecomeZeroOrFallbackSilently(){for(Object value:new Object[]{0,-1,"2500",Double.NaN}){JSONObject r=row("daily","2026-11-09",1,2500,"approved");if(value instanceof Double&&Double.isNaN((Double)value))r.put("calories_kcal",JSONObject.NULL);else r.put("calories_kcal",value);assertThrows(IllegalArgumentException.class,()->NutritionTargets.validate(new JSONArray().put(r)));}assertThrows(IllegalArgumentException.class,()->NutritionTargets.validate(new JSONArray().put(row("daily","2026-02-30",1,2500,"approved"))));}
}
